;

// _lib.ts's shared addEdge() only dedupes on source+target+type -- blind to
// the new `method` attribute this migration relies on. Several ingredients
// (Rain Water, Sylvan Berries, Drake Egg, ...) are genuinely both dropped
// and foraged at the very same zone, so a method-aware check is needed or
// the second call would silently no-op against the first.
function addLocatedInEdge(itemId: string, zoneId: string, method: "drop" | "forage" | "fish", mobs?: string[]) {
  const exists = graph.edges.some(
    (e: { source: string; target: string; type: string; method?: string }) =>
      e.source === itemId && e.target === zoneId && e.type === "located_in" && e.method === method
  );
  if (exists) return;
  const edge: Record<string, unknown> = { id: `e-located-${graph.edges.length + 1}`, source: itemId, target: zoneId, type: "located_in", method };
  if (mobs?.length) edge.mobs = mobs;
  graph.edges.push(edge);
}

let skippedMissingItem = 0;
let addedDrop = 0, addedForage = 0, addedFish = 0;
for (const entry of DATA) {
  if (!hasNode(entry.itemId)) { skippedMissingItem++; console.log("skip (item not in graph):", entry.itemId, entry.label); continue; }
  for (const z of entry.drops) { addLocatedInEdge(entry.itemId, z.zoneId, "drop", z.mobs); addedDrop++; }
  for (const z of entry.forage) { addLocatedInEdge(entry.itemId, z.zoneId, "forage"); addedForage++; }
  for (const z of entry.fish) { addLocatedInEdge(entry.itemId, z.zoneId, "fish"); addedFish++; }
}

save();
console.log(`Added sourcing edges for ${DATA.length} ingredients: ${addedDrop} drop, ${addedForage} forage, ${addedFish} fish. Skipped ${skippedMissingItem} (item id not found).`);
